using System;
using System.IO;
using System.Collections.Generic;
using NUnit.Framework;
using Olca.Unity;
using UnityEngine.InputSystem;
namespace Olca.Tests {
 public class GamepadVibrationTests {
  Gamepad pad,other;GamepadVibrationAdapter adapter;double now;List<(Gamepad,float,float)> sent;
  [SetUp] public void Setup(){now=0;pad=InputSystem.AddDevice<Gamepad>();other=InputSystem.AddDevice<Gamepad>();sent=new List<(Gamepad,float,float)>();adapter=new GamepadVibrationAdapter(()=>now,(d,l,h)=>sent.Add((d,l,h)));}
  [TearDown] public void Cleanup(){adapter.Dispose();if(pad.added)InputSystem.RemoveDevice(pad);if(other.added)InputSystem.RemoveDevice(other);}
  [Test] public void 未設定と既定無効は出力せず明示設定後だけ出力する(){Assert.IsFalse(adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1)));adapter.Enabled=true;Assert.IsFalse(adapter.TryPlay(pad,null));Assert.IsEmpty(sent);Assert.IsTrue(adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1)));Assert.AreEqual((pad,.2f,.4f),sent[0]);}
  [Test] public void 指定終了と無効化は停止し再有効化で自動再開しない(){adapter.Enabled=true;adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));now=.99;adapter.Tick();Assert.IsTrue(adapter.IsPlaying);now=1;adapter.Tick();Assert.IsFalse(adapter.IsPlaying);Assert.AreEqual((pad,0f,0f),sent[sent.Count-1]);adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));adapter.Enabled=false;Assert.IsFalse(adapter.IsPlaying);int count=sent.Count;adapter.Enabled=true;adapter.Tick();Assert.AreEqual(count,sent.Count);}
  [Test] public void 機器切替は前の機器を停止し取消と破棄も出力を解放する(){adapter.Enabled=true;adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));adapter.TryPlay(other,new GamepadVibrationRequest(.3f,.5f,2));Assert.AreEqual((pad,0f,0f),sent[1]);Assert.AreEqual((other,.3f,.5f),sent[2]);adapter.Stop();Assert.AreEqual((other,0f,0f),sent[3]);adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));adapter.Dispose();Assert.IsFalse(adapter.IsPlaying);Assert.IsFalse(adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1)));}
  [Test] public void 切断と機器無効化は停止し別機器のイベントで停止しない(){adapter.Enabled=true;adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));InputSystem.DisableDevice(other);Assert.IsTrue(adapter.IsPlaying);InputSystem.DisableDevice(pad);Assert.IsFalse(adapter.IsPlaying);Assert.IsFalse(adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1)));InputSystem.EnableDevice(pad);adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));InputSystem.RemoveDevice(pad);Assert.IsFalse(adapter.IsPlaying);}
  [Test] public void 強さゼロと未設定への変更は以前の出力も停止する(){adapter.Enabled=true;adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));Assert.IsFalse(adapter.TryPlay(pad,new GamepadVibrationRequest(0,0,1)));Assert.IsFalse(adapter.IsPlaying);adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,1));Assert.IsFalse(adapter.TryPlay(pad,null));Assert.IsFalse(adapter.IsPlaying);}
  [TestCase(-1,.5f,1)][TestCase(.5f,2,1)][TestCase(.5f,.5f,0)][TestCase(float.NaN,.5f,1)][TestCase(.5f,.5f,double.PositiveInfinity)] public void 不正明示値は拒否する(float low,float high,double seconds){Assert.Throws<ArgumentOutOfRangeException>(()=>new GamepadVibrationRequest(low,high,seconds));}
  [Test] public void 仮想機器の実APIでも切断後の振動キャッシュをゼロへ戻し再開で復活させない(){adapter.Dispose();adapter=new GamepadVibrationAdapter();adapter.Enabled=true;Assert.IsTrue(adapter.TryPlay(pad,new GamepadVibrationRequest(.2f,.4f,10)));InputSystem.RemoveDevice(pad);Assert.IsFalse(adapter.IsPlaying);var field=typeof(Gamepad).GetField("m_Rumble",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);Func<bool> rumbling=()=>{var state=field.GetValue(pad);return (bool)state.GetType().GetProperty("isRumbling").GetValue(state);};Assert.IsFalse(rumbling());pad.ResumeHaptics();Assert.IsFalse(rumbling());}
  string directory;
  [Test] public void 振動設定は既定無効で保存後だけ読込値を変える(){directory=Path.Combine(Path.GetTempPath(),"olca-vibration-"+Guid.NewGuid().ToString("N"));try{var store=new GamepadVibrationSettingsStore(directory);Assert.IsTrue(store.TryRead(out var enabled,out _));Assert.IsFalse(enabled);Assert.IsFalse(File.Exists(store.ActivePath));Assert.IsTrue(store.TrySave(true,out var error),error);Assert.IsTrue(new GamepadVibrationSettingsStore(directory).TryRead(out enabled,out error),error);Assert.IsTrue(enabled);Assert.IsTrue(store.TrySave(false,out error),error);Assert.IsTrue(store.TryRead(out enabled,out error));Assert.IsFalse(enabled);}finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}}
  [Test] public void 壊れた振動設定は上書きせず無効として読込失敗を報告する(){directory=Path.Combine(Path.GetTempPath(),"olca-vibration-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(directory);var store=new GamepadVibrationSettingsStore(directory);File.WriteAllText(store.ActivePath,"broken");Assert.IsFalse(store.TryRead(out var enabled,out _));Assert.IsFalse(enabled);Assert.IsFalse(store.TrySave(true,out _));Assert.AreEqual("broken",File.ReadAllText(store.ActivePath));}finally{Directory.Delete(directory,true);}}
  class Fault:CheckpointFileIo {public override void Replace(string a,string b,string c)=>throw new IOException("fixture");}
  [Test] public void 振動設定保存の失敗は元の値を保持して再試行できる(){directory=Path.Combine(Path.GetTempPath(),"olca-vibration-"+Guid.NewGuid().ToString("N"));try{var store=new GamepadVibrationSettingsStore(directory);Assert.IsTrue(store.TrySave(false,out _));var before=File.ReadAllBytes(store.ActivePath);Assert.IsFalse(new GamepadVibrationSettingsStore(directory,new Fault()).TrySave(true,out _));CollectionAssert.AreEqual(before,File.ReadAllBytes(store.ActivePath));Assert.IsTrue(store.TrySave(true,out _));Assert.IsTrue(store.TryRead(out var enabled,out _));Assert.IsTrue(enabled);}finally{Directory.Delete(directory,true);}}
 }
}
